-- Generated current-job quest profile. Regenerate with scripts/generate_class_profile.py.
if NoobgamClassQuests and NoobgamClassQuests.Profile then return NoobgamClassQuests end
---@class BundledClassQuest
---@field id integer
---@field job integer|nil
---@field jobs table<integer, boolean>
---@field branches table<integer, boolean>
---@field level number
---@field name string
---@field prereq table<string, boolean>
---@field steps table<integer, table>
---@class BundledClassQuestAPI
---@field Name string
---@field Quests table<integer, BundledClassQuest>
---@field Misc table[]
---@field Profile table
---@field NeedsBlock boolean
---@field Interactions table<integer, boolean>
---@field CharacterKey string|nil
---@field LevelCap number|nil
---@field Options table[]
---@field GetPinnedJob fun(): integer|nil
---@field UseSoulCrystal fun(job: integer): boolean
---@field IsCurrentJob fun(questId: integer): boolean
---@field EnsureRegistered fun(): boolean|nil, string|nil
---@field HasWork fun(levelCap?: number): boolean|nil, integer|string|nil
NoobgamClassQuests = NoobgamClassQuests or {}
local P = NoobgamClassQuests
P.Name = "Noobgam Class Quests (Current Job)"
P.Quests = {}
P.Misc = {}
P.NeedsBlock = false
P.Interactions = {}
local compiled = {}
local orderedIds = {}
local pinVariable = "NoobgamClassQuestPinnedJob"
local jobIds = {
    Paladin = 19, Monk = 20, Warrior = 21, Dragoon = 22, Bard = 23,
    ["White Mage"] = 24, ["Black Mage"] = 25, Summoner = 27, Scholar = 28,
    Ninja = 30, Machinist = 31, ["Dark Knight"] = 32, Astrologian = 33,
    Samurai = 34, ["Red Mage"] = 35, ["Blue Mage"] = 36, Gunbreaker = 37,
    Dancer = 38, Reaper = 39, Sage = 40, Viper = 41, Pictomancer = 42,
}
local baseClasses = {
    [19] = 1, [20] = 2, [21] = 3, [22] = 4, [23] = 5,
    [24] = 6, [25] = 7, [27] = 26, [28] = 26, [30] = 29,
}

-- The profile UI persists options in Settings.Questing. Read saved values when
-- Bootstrap checks availability while another quest profile is selected.
---@return integer|nil
function P.GetPinnedJob()
    local selection
    if gQuestProfile == P.Name then selection = _G[pinVariable] end
    if selection == nil and Settings.Questing then selection = Settings.Questing[pinVariable] end
    local job = jobIds[selection or "Current job"]
    if job and (Player.job == job or Player.job == baseClasses[job]) then return job end
end

---@param job integer
---@return boolean
function P.UseSoulCrystal(job)
    if Player.job ~= baseClasses[job] then return false end
    return (P.GetPinnedJob() or (Player.job == 26 and 27) or job) == job
end

P.Options = {{
    type = "combobox", tab = "Classes", display = "Pin job",
    var = pinVariable, default = "Current job",
    list = "Current job,Paladin,Monk,Warrior,Dragoon,Bard,White Mage,Black Mage,Summoner,Scholar,Ninja,Machinist,Dark Knight,Astrologian,Samurai,Red Mage,Blue Mage,Gunbreaker,Dancer,Reaper,Sage,Viper,Pictomancer",
}}

---@param questId integer
---@return boolean
function P.IsCurrentJob(questId)
    local quest = P.Quests[questId]
    local pin = P.GetPinnedJob()
    return quest ~= nil and quest.jobs[Player.job] == true
        and (pin == nil or quest.branches[pin] == true)
        and quest.level <= math.min(Player.level, P.LevelCap or 100)
end

-- Captured condition groups are conjunctive. Errors stay unknown, never eligible.
---@param conditions table
---@return boolean|nil
---@return string|nil
local function matches(conditions)
    for expression, expected in pairs(conditions or {}) do
        if type(expected) == "table" then
            local ok, err = matches(expected)
            if ok ~= true then return ok, err end
        else
            local fn = compiled[expression]
            if fn == nil then
                local err
                fn, err = loadstring("return " .. expression)
                if fn == nil then return nil, err end
                compiled[expression] = fn
            end
            local ok, value = pcall(fn)
            if not ok then return nil, "condition failed: " .. expression end
            if value ~= expected then return false end
        end
    end
    return true
end

local function resetCharacterState()
    local key = Player.name .. ":" .. tostring(Player.homeworld)
    if P.CharacterKey ~= key then
        P.CharacterKey = key
        P.NeedsBlock = false
        P.Interactions = {}
    end
end

---@return boolean|nil ready
---@return string|nil error
function P.EnsureRegistered()
    local api = FFXIVLib and FFXIVLib.Questing
    if not api or not api.AddProfile or not api.profilesDisplay then
        return nil, "FFXIVLib questing is not ready"
    end
    for _, name in pairs(api.profilesDisplay) do
        if name == P.Name then return true end
    end
    api.AddProfile(P.Profile)
    for _, name in pairs(api.profilesDisplay) do
        if name == P.Name then return true end
    end
    return nil, "class profile registration did not publish its name"
end

---@param levelCap number|nil
---@return boolean|nil available
---@return integer|string|nil questOrError
function P.HasWork(levelCap)
    if MGetGameState() ~= FFXIV.GAMESTATE.INGAME or Player.localmapid == 0 then
        return nil, "character is loading"
    end
    resetCharacterState()
    P.LevelCap = levelCap or 100
    local level = math.min(Player.level, P.LevelCap)
    -- Finish the current class's promotion using its already-earned soul crystal.
    if level >= 30 then
        for _, task in ipairs(P.Misc) do
            local eligible, err = matches(task.condition)
            if eligible == nil then return nil, err end
            if eligible and not IsEquipped(task.itemid) and ItemCount(task.itemid, true) > 0 then
                return true, "soul crystal"
            end
        end
    end
    for _, id in ipairs(orderedIds) do
        local quest = P.Quests[id]
        if P.IsCurrentJob(id) and quest.level <= level and not QuestCompleted(id) then
            if HasQuest(id) then return true, id end
            local eligible, err = matches(quest.prereq)
            if eligible == nil then return nil, err end
            if eligible then return true, id end
        end
    end
    return false
end

