-- Build the executable profile once from the compact quest records.
-- The shared guard enforces quest.jobs, the branch pin and level at both selection
-- and step execution, so authored conditions only need additional restrictions.
local function idSet(ids)
    local result = {}
    for _, id in ipairs(ids) do result[id] = true end
    return result
end

local function addQuests(quests, job)
    local defaultBranches = {}
    if job then
        for promoted, base in pairs(baseClasses) do
            if base == job then defaultBranches[promoted] = true end
        end
        if next(defaultBranches) == nil then defaultBranches[job] = true end
    end
    for id, quest in pairs(quests) do
        quest.id = id
        quest.job = job
        quest.jobs = job and { [job] = true } or idSet(quest.jobs)
        quest.branches = quest.branches and idSet(quest.branches) or (job and defaultBranches or quest.jobs)
        local guard = "NoobgamClassQuests.IsCurrentJob(" .. id .. ")"
        quest.prereq = quest.prereq or {}
        quest.prereq[guard] = true
        for _, step in pairs(quest.steps) do
            step.condition = step.condition or {}
            step.condition[guard] = true
        end
        P.Quests[id] = quest
        orderedIds[#orderedIds + 1] = id
    end
end

for job, quests in pairs(jobSpecificQuests) do addQuests(quests, job) end
for _, quests in pairs(roleQuests) do addQuests(quests) end
table.sort(orderedIds)
P.Profile = { names = { en = P.Name, de = P.Name, fr = P.Name, jp = P.Name, ja = P.Name, cn = P.Name, kr = P.Name, tc = P.Name }, quests = P.Quests, misc = P.Misc, vars = P.Options }
return P
